#include "core/dataset.h"
#include <filesystem>
#include <iomanip>
#include <sstream>
#include <regex>
namespace fs=std::filesystem;
namespace {
std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='\\')o+="\\\\";else if(c=='\"')o+="\\\"";else if(c=='\n')o+="\\n";else o+=c;}return o;}
std::string strv(const std::string&t,const std::string&k,const std::string&d){std::regex r("\\\""+k+"\\\"\\s*:\\s*\\\"((?:\\\\.|[^\\\"])*)\\\"");std::smatch m;if(!std::regex_search(t,m,r))return d;std::string v=m[1],o;for(size_t i=0;i<v.size();++i){if(v[i]=='\\'&&i+1<v.size()){char n=v[++i];o+=(n=='n'?'\n':n);}else o+=v[i];}return o;}
template<class T>T numv(const std::string&t,const std::string&k,T d){std::regex r("\\\""+k+"\\\"\\s*:\\s*([-+0-9.eE]+)");std::smatch m;if(!std::regex_search(t,m,r))return d;std::istringstream is(m[1]);T v{};return(is>>v)?v:d;}
void manifest(const std::string&d,const DatasetSpec&s,const std::string&st,uint64_t n){std::ofstream f(fs::path(d)/"manifest.json",std::ios::trunc);f<<"{\n  \"schema_version\": 2,\n  \"task\": {\n    \"task_id\": \""<<esc(s.taskId)<<"\",\n    \"display_name\": \""<<esc(s.displayName)<<"\",\n    \"task_type\": \""<<esc(s.taskType)<<"\",\n    \"model_family\": \""<<esc(s.modelFamily)<<"\"\n  },\n  \"sample_rate\": "<<s.sampleRate<<",\n  \"window_samples\": "<<s.windowSamples<<",\n  \"stride_samples\": "<<s.strideSamples<<",\n  \"channels\": [";for(size_t i=0;i<s.channels.size();++i)f<<(i?",":"")<<int(s.channels[i]);f<<"],\n  \"labels\": [";if(!s.labelSpecs.empty()){for(size_t i=0;i<s.labelSpecs.size();++i)f<<(i?",":"")<<"{\"id\":\""<<esc(s.labelSpecs[i].id)<<"\",\"name\":\""<<esc(s.labelSpecs[i].displayName)<<"\"}";}else{for(size_t i=0;i<s.labels.size();++i)f<<(i?",":"")<<"{\"id\":\""<<esc(s.labels[i])<<"\",\"name\":\""<<esc(s.labels[i])<<"\"}";}f<<"],\n  \"preprocessing\": \""<<esc(s.preprocessing)<<"\",\n  \"normalization\": \""<<esc(s.normalization)<<"\",\n  \"training\": {\"epochs\": "<<s.training.epochs<<", \"batch_size\": "<<s.training.batchSize<<", \"learning_rate\": "<<s.training.learningRate<<", \"validation_split\": "<<s.training.validationSplit<<", \"seed\": "<<s.training.seed<<", \"device\": \""<<esc(s.training.device)<<"\"},\n  \"examples\": "<<n<<",\n  \"status\": \""<<esc(st)<<"\"\n}\n";}
}
bool DatasetWriter::open(const std::string&d,const DatasetSpec&s){m_dir=d;m_spec=s;m_id=0;try{fs::create_directories(fs::path(d)/"data");}catch(...){return false;}manifest(m_dir,m_spec,"in_progress",0);m_index.open(fs::path(d)/"examples.jsonl",std::ios::app);m_open=bool(m_index);return m_open;}
bool DatasetWriter::append(const std::string&label,const std::vector<std::vector<int32_t>>&w,uint64_t src){if(!m_open||w.size()!=m_spec.channels.size())return false;size_t n=w.empty()?0:w[0].size();for(const auto&c:w)if(c.size()!=n)return false;std::ostringstream fn;fn<<"data/chunk-"<<std::setw(8)<<std::setfill('0')<<m_id<<".bin";std::ofstream f(fs::path(m_dir)/fn.str(),std::ios::binary);if(!f)return false;for(size_t i=0;i<n;++i)for(size_t c=0;c<w.size();++c)f.write(reinterpret_cast<const char*>(&w[c][i]),4);f.close();m_index<<"{\"id\":"<<m_id<<",\"label\":\""<<esc(label)<<"\",\"source_sample\":"<<src<<",\"samples\":"<<n<<",\"file\":\""<<fn.str()<<"\"}\n";++m_id;return true;}
void DatasetWriter::finish(const std::string&st){if(!m_open)return;m_index.close();manifest(m_dir,m_spec,st,m_id);m_open=false;}
bool loadDatasetManifest(const std::string&d,DatasetSpec&s,size_t*examples,std::string*status,std::string*error){std::ifstream f(fs::path(d)/"manifest.json");if(!f){if(error)*error="manifest.json not found";return false;}std::string t((std::istreambuf_iterator<char>(f)),{});int v=numv<int>(t,"schema_version",1);if(v<1||v>2){if(error)*error="unsupported schema version";return false;}s.taskId=strv(t,"task_id",s.taskId);s.displayName=strv(t,"display_name",s.displayName);s.taskType=strv(t,"task_type",s.taskType);s.modelFamily=strv(t,"model_family",s.modelFamily);s.sampleRate=numv<uint32_t>(t,"sample_rate",s.sampleRate);s.windowSamples=numv<size_t>(t,"window_samples",s.windowSamples);s.strideSamples=numv<size_t>(t,"stride_samples",s.strideSamples);s.preprocessing=strv(t,"preprocessing",s.preprocessing);s.normalization=strv(t,"normalization",s.normalization);s.channels.clear();std::regex ar("\\\"channels\\\"\\s*:\\s*\\[([^\\]]*)\\]");std::smatch am;if(std::regex_search(t,am,ar)){std::regex iv("[0-9]+");for(std::sregex_iterator it(am[1].first,am[1].second,iv),e;it!=e;++it)s.channels.push_back(static_cast<uint8_t>(std::stoi(it->str())));}s.labels.clear();s.labelSpecs.clear();std::regex lr("\\\"name\\\"\\s*:\\s*\\\"([^\\\"]*)\\\"");for(std::sregex_iterator it(t.begin(),t.end(),lr),e;it!=e;++it){s.labels.push_back((*it)[1].str());s.labelSpecs.push_back({(*it)[1].str(),(*it)[1].str()});}if(examples)*examples=numv<size_t>(t,"examples",0);if(status)*status=strv(t,"status","unknown");return true;}
